#define main prior_graph_main
#include "graph-check.cpp"
#undef main
#include <chrono>
#include <array>
#include <climits>
using Clock=std::chrono::steady_clock;
long long ns(Clock::time_point a,Clock::time_point b){return std::chrono::duration_cast<std::chrono::nanoseconds>(b-a).count();}
struct Dag{obs_source_t *root;std::vector<std::array<obs_source_t*,2>> levels;};
Dag dag(int depth){Dag d;d.root=source("cost root");for(int l=0;l<depth;l++){d.levels.push_back({source("cost A"),source("cost B")});if(l==0){for(auto *child:d.levels[l]){if(!obs_source_add_active_child(d.root,child))std::abort();node(d.root)->visual.push_back(child);}}else{for(auto *parent:d.levels[l-1])for(auto *child:d.levels[l]){if(!obs_source_add_active_child(parent,child))std::abort();node(parent)->visual.push_back(child);}}}return d;}
void dispose(Dag &d){for(int l=int(d.levels.size())-2;l>=0;l--)for(auto *parent:d.levels[l]){for(auto *child:d.levels[l+1])obs_source_remove_active_child(parent,child);node(parent)->visual.clear();}for(auto *c:d.levels[0])obs_source_remove_active_child(d.root,c);node(d.root)->visual.clear();for(auto &level:d.levels)for(auto *s:level)obs_source_release(s);obs_source_release(d.root);studio_graph_drain();}
int main(int argc,char **argv){if(argc!=2||std::filesystem::exists(argv[1]))return 2;checks=obs_data_array_create();auto *times=obs_data_array_create();check(obs_startup("en-US",nullptr,nullptr),"Native cost core startup");obs_source_info i{};i.id="graph_probe";i.type=OBS_SOURCE_TYPE_INPUT;i.output_flags=OBS_SOURCE_AUDIO;i.get_name=name;i.create=create;i.destroy=destroy;i.enum_active_sources=enumerate;i.enum_all_sources=enumerate;obs_register_source(&i);auto *probe=source("independent gate probe");for(int depth:{25}){auto d=dag(depth);std::atomic<bool> done{false};long long activateNs=0;std::thread worker([&]{auto a=Clock::now();obs_source_inc_active(d.root);activateNs=ns(a,Clock::now());done=true;});while(studio_graph_show(d.root)==0&&!done.load())std::this_thread::yield();const bool observedRunning=!done.load();auto a=Clock::now();obs_source_inc_showing(probe);long long probeNs=ns(a,Clock::now());obs_source_dec_showing(probe);worker.join();long expected=1L<<(depth-1);count(d.levels.back()[0],expected,expected,"Layered DAG depth"+std::to_string(depth)+" exact multiplicity");auto *e=obs_data_create();obs_data_set_int(e,"depth",depth);obs_data_set_int(e,"vertices",1+2*depth);obs_data_set_int(e,"edges",2+4*(depth-1));obs_data_set_int(e,"root_to_one_leaf_paths",expected);obs_data_set_int(e,"legacy_recursive_node_visits",(1LL<<(depth+1))-1);obs_data_set_int(e,"activate_ns",activateNs);obs_data_set_int(e,"independent_probe_wait_ns",probeNs);obs_data_set_bool(e,"observed_root_update_in_progress_before_probe",observedRunning);auto begin=Clock::now();obs_source_dec_active(d.root);obs_data_set_int(e,"deactivate_ns",ns(begin,Clock::now()));count(d.levels.back()[0],0,0,"Layered DAG depth"+std::to_string(depth)+" exact cleanup");
 // Add a second root to an existing deep, INACTIVE DAG: delta(0,0) still traverses.
 auto *inactive=source("inactive attachment parent");begin=Clock::now();check(obs_source_add_active_child(inactive,d.root),"Inactive attachment depth"+std::to_string(depth)+" succeeds");obs_data_set_int(e,"inactive_add_api_ns",ns(begin,Clock::now()));begin=Clock::now();obs_source_remove_active_child(inactive,d.root);obs_data_set_int(e,"inactive_remove_gate_api_ns",ns(begin,Clock::now()));obs_source_release(inactive);obs_data_array_push_back(times,e);obs_data_release(e);dispose(d);}
 obs_source_release(probe);studio_graph_drain();obs_shutdown();auto *r=obs_data_create();obs_data_set_array(r,"checks",checks);obs_data_set_array(r,"measurements",times);obs_data_set_int(r,"failures",failures);obs_data_set_bool(r,"passed",!failures);obs_data_set_string(r,"scope","Native timing witnesses; passing count criteria do not imply gate latency acceptance. No fixed latency threshold is relaxed.");obs_data_save_json_safe(r,argv[1],"tmp",nullptr);obs_data_release(r);obs_data_array_release(checks);obs_data_array_release(times);return failures?1:0;}
